import unittest
from candidate import has_close_elements


class TestHasCloseElements(unittest.TestCase):

    def test_close_elements_found_returns_true(self):
        self.assertTrue(has_close_elements([1.0, 2.8, 3.0, 4.0, 5.0, 2.0], 0.3))

    def test_no_close_elements_returns_false(self):
        self.assertFalse(has_close_elements([1.0, 2.0, 3.0], 0.5))

    def test_empty_list_returns_false(self):
        self.assertFalse(has_close_elements([], 0.5))

    def test_single_element_returns_false(self):
        self.assertFalse(has_close_elements([1.0], 0.5))

    def test_two_elements_within_threshold(self):
        self.assertTrue(has_close_elements([1.0, 1.2], 0.5))

    def test_two_elements_outside_threshold(self):
        self.assertFalse(has_close_elements([1.0, 2.0], 0.5))

    def test_distance_exactly_equals_threshold_returns_false(self):
        self.assertFalse(has_close_elements([1.0, 1.5], 0.5))

    def test_distance_just_below_threshold_returns_true(self):
        self.assertTrue(has_close_elements([1.0, 1.49], 0.5))

    def test_negative_numbers_close(self):
        self.assertTrue(has_close_elements([-1.0, -0.8, 0.0], 0.3))

    def test_negative_numbers_not_close(self):
        self.assertFalse(has_close_elements([-1.0, -2.0, -3.0], 0.5))

    def test_duplicate_elements_with_positive_threshold(self):
        self.assertTrue(has_close_elements([1.0, 1.0], 0.1))

    def test_duplicate_elements_with_zero_threshold(self):
        self.assertFalse(has_close_elements([1.0, 1.0], 0.0))

    def test_all_same_elements(self):
        self.assertTrue(has_close_elements([5.0, 5.0, 5.0], 0.1))

    def test_all_same_elements_zero_threshold(self):
        self.assertFalse(has_close_elements([5.0, 5.0, 5.0], 0.0))

    def test_large_numbers_close(self):
        self.assertTrue(has_close_elements([1000000.0, 1000000.5], 1.0))

    def test_large_numbers_not_close(self):
        self.assertFalse(has_close_elements([1000000.0, 2000000.0], 1.0))

    def test_mixed_positive_and_negative_close(self):
        self.assertTrue(has_close_elements([-0.1, 0.1, 10.0], 0.5))

    def test_mixed_positive_and_negative_not_close(self):
        self.assertFalse(has_close_elements([-1.0, 1.0, 10.0], 0.5))

    def test_int_elements_close(self):
        self.assertTrue(has_close_elements([1, 1], 1.0))

    def test_int_elements_not_close(self):
        self.assertFalse(has_close_elements([1, 3, 5], 0.5))

    def test_very_small_threshold(self):
        self.assertTrue(has_close_elements([1.0, 1.0000001], 0.000001))

    def test_very_small_threshold_not_close(self):
        self.assertFalse(has_close_elements([1.0, 1.0000002], 0.000001))

    def test_close_pair_at_end_of_list(self):
        self.assertTrue(has_close_elements([10.0, 20.0, 30.0, 30.1], 0.5))

    def test_close_pair_at_start_of_list(self):
        self.assertTrue(has_close_elements([1.0, 1.1, 10.0, 20.0], 0.5))

    def test_close_pair_in_middle_of_list(self):
        self.assertTrue(has_close_elements([10.0, 20.0, 20.1, 30.0], 0.5))

    def test_zero_threshold_no_duplicates(self):
        self.assertFalse(has_close_elements([1.0, 2.0, 3.0], 0.0))

    def test_float_precision_close(self):
        self.assertTrue(has_close_elements([0.1, 0.2], 0.15))

    def test_float_precision_not_close(self):
        self.assertFalse(has_close_elements([0.1, 0.3], 0.15))

    def test_none_in_list_raises_type_error(self):
        with self.assertRaises(TypeError):
            has_close_elements([None, 1.0], 0.5)

    def test_string_in_list_raises_type_error(self):
        with self.assertRaises(TypeError):
            has_close_elements(["a", 1.0], 0.5)

    def test_none_threshold_raises_type_error(self):
        with self.assertRaises(TypeError):
            has_close_elements([1.0, 2.0], None)

    def test_none_numbers_raises_type_error(self):
        with self.assertRaises(TypeError):
            has_close_elements(None, 0.5)

    def test_two_elements_negative_close(self):
        self.assertTrue(has_close_elements([-5.0, -4.9], 0.2))

    def test_two_elements_negative_not_close(self):
        self.assertFalse(has_close_elements([-5.0, -4.0], 0.2))

    def test_many_elements_one_pair_close(self):
        self.assertTrue(has_close_elements([1.0, 5.0, 10.0, 20.0, 20.01, 50.0], 0.1))

    def test_many_elements_no_pair_close(self):
        self.assertFalse(has_close_elements([1.0, 5.0, 10.0, 20.0, 50.0, 100.0], 0.1))

    def test_threshold_larger_than_all_distances(self):
        self.assertTrue(has_close_elements([1.0, 2.0], 100.0))

    def test_zero_values_close(self):
        self.assertTrue(has_close_elements([0.0, 0.0], 0.1))

    def test_zero_values_zero_threshold(self):
        self.assertFalse(has_close_elements([0.0, 0.0], 0.0))


if __name__ == '__main__':
    unittest.main()
